if (lastSeen === 0) return null; // 아직 초기 수신 전이면 대기
if (silentMs < 15000) return null; // 15초 이내 수신 있음
if (now - cooldown < 15000) return null; // 과도한 재구독 방지
flow.set('opcua_resub_cooldown_TEST-01', now);
msg.topic = 'multiple';
