// 1초마다 라인 페이로드 발행
// 집계된 설비 값을 그대로 payload / OPC UA 로 노출한다.
const LINE_ID = "LINE-01";
const SCHEMA_VERSION = "1.0";
const EQUIPMENTS = ["CAST-01", "CNC-01", "CNC-02", "CNC-03", "WASH-01", "ASSY-01", "ASSY-02", "TEST-01", "TEST-02"];
const EXPECTED_TAGS = {"CAST-01": {"power": "bool", "injection_pressure_sp": "float", "mold_temperature_sp": "float", "cooling_flow_sp": "float", "injection_pressure": "float", "mold_temperature": "float", "cooling_flow": "float", "progress": "float"}, "CNC-01": {"power": "bool", "spindle_speed_sp": "int", "tool_usage_sp": "float", "coolant_flow_sp": "float", "spindle_speed": "int", "tool_usage": "float", "coolant_flow": "float", "progress": "float"}, "CNC-02": {"power": "bool", "spindle_speed_sp": "int", "tool_usage_sp": "float", "coolant_flow_sp": "float", "spindle_speed": "int", "tool_usage": "float", "coolant_flow": "float", "progress": "float"}, "CNC-03": {"power": "bool", "spindle_speed_sp": "int", "tool_usage_sp": "float", "coolant_flow_sp": "float", "spindle_speed": "int", "tool_usage": "float", "coolant_flow": "float", "progress": "float"}, "WASH-01": {"power": "bool", "cleaning_concentration_sp": "float", "cleaning_temperature_sp": "float", "cleaning_pressure_sp": "float", "cleaning_concentration": "float", "cleaning_temperature": "float", "cleaning_pressure": "float", "progress": "float"}, "ASSY-01": {"power": "bool", "tightening_torque_sp": "float", "tightening_angle_sp": "float", "press_force_sp": "float", "tightening_torque": "float", "tightening_angle": "float", "press_force": "float", "progress": "float"}, "ASSY-02": {"power": "bool", "tightening_torque_sp": "float", "tightening_angle_sp": "float", "press_force_sp": "float", "tightening_torque": "float", "tightening_angle": "float", "press_force": "float", "progress": "float"}, "TEST-01": {"power": "bool", "bore_dimension_sp": "float", "hole_dimension_sp": "float", "bore_dimension": "float", "hole_dimension": "float", "result_ok": "bool", "progress": "float"}, "TEST-02": {"power": "bool", "bore_dimension_sp": "float", "hole_dimension_sp": "float", "bore_dimension": "float", "hole_dimension": "float", "result_ok": "bool", "progress": "float"}};
function defaultForType(t) {
  if (t === 'bool') return false;
  if (t === 'int') return 0;
  if (t === 'float') return 0.0;
  return '';
}
const STALE_MS = 3000;
const buf = flow.get('equipments') || {};
const now = Date.now();
const nowIso = new Date(now).toISOString();
function deriveQuality(last_update_ms) {
  if (!last_update_ms) return 'BAD';
  if (now - last_update_ms > STALE_MS) return 'UNCERTAIN';
  return 'GOOD';
}
const equipments = {};
for (const eq_id of EQUIPMENTS) {
  const slot = buf[eq_id] || {};
  const data = Object.assign({}, slot.data || {});
  const expected = EXPECTED_TAGS[eq_id] || {};
  for (const [tagName, tagType] of Object.entries(expected)) {
    if (!(tagName in data)) data[tagName] = defaultForType(tagType);
  }
  equipments[eq_id] = {
    status: ('status' in data) ? String(data.status) : 'UNKNOWN',
    ts: slot.last_update_ms ? new Date(slot.last_update_ms).toISOString() : nowIso,
    quality: deriveQuality(slot.last_update_ms),
    data: data,
  };
}
const payload = {
  ts: nowIso,
  line_id: LINE_ID,
  schema_version: SCHEMA_VERSION,
  equipments: equipments,
};
return { payload: payload };

const now = new Date().toISOString();
const cmd = (msg.payload || {}).command || msg.payload || {};

const equipmentId = cmd.equipment_id || cmd.target_equipment || cmd.machine_id;
const commandId   = cmd.command_id   || msg.command_id       || msg._msgid;
let rawType       = cmd.command_type || cmd.tag              || cmd.tag_name || cmd.name;
let value         = 'value' in cmd   ? cmd.value             : cmd.payload;

if (!equipmentId || !rawType) {
  msg.command_result = {
    command_id: commandId || null, equipment_id: equipmentId || null,
    command_type: rawType || null, status: 'REJECTED_INVALID', accepted: false,
    requested_at: now, updated_at: now,
    last_error: 'equipment_id or command_type missing'
  };
  return [null, msg];
}

// 입력 표기가 다를 수 있는 것만 정규화
const ALIAS = {
  inject_warn:  'inject_warning',
  load:         'load_request',
  unload:       'unload_request'
};
const commandType = ALIAS[rawType] ?? rawType;

const BOOL_TAGS = new Set(['power', 'load_request', 'unload_request', 'reset_error', 'inject_warning', 'inject_error']);
if (BOOL_TAGS.has(commandType)) value = !!value;

const inflightMap = flow.get('equipment_inflight_map') || {};
if (inflightMap[equipmentId]) {
  msg.command_result = {
    command_id: commandId, equipment_id: equipmentId, command_type: commandType,
    status: 'REJECTED_BUSY', accepted: false, requested_at: now, updated_at: now,
    last_error: 'another command is already in-flight for this equipment',
    inflight_command_id: inflightMap[equipmentId].command_id
  };
  return [null, msg];
}

const timeoutSec = Number(cmd.timeout_sec || 10);
inflightMap[equipmentId] = { command_id: commandId, command_type: commandType, started_at: now, timeout_sec: timeoutSec };
flow.set('equipment_inflight_map', inflightMap);

const statusMap = flow.get('command_status_map') || {};
statusMap[commandId] = {
  command_id: commandId, equipment_id: equipmentId, command_type: commandType,
  value, status: 'SENDING', accepted: true,
  requested_at: now, updated_at: now, retry_count: 0, last_error: null
};
flow.set('command_status_map', statusMap);

msg.command        = { command_id: commandId, equipment_id: equipmentId, command_type: commandType, value, timeout_sec: timeoutSec };
msg.command_result = statusMap[commandId];
msg.topic          = commandId;
return [msg, null];

