const now = new Date().toISOString();
const c = msg.command || {};
if (!c.command_id) return null;
const kind = String(msg.writer_kind || '').toLowerCase();
const payload = msg.payload;
const result = {
  protocol: msg.protocol || (kind.startsWith('opcua') ? 'opcua' : (kind.startsWith('modbus') ? 'modbus' : (kind.startsWith('mc') ? 'mcprotocol' : 'unknown'))),
  writer_kind: msg.writer_kind || null,
  writer_target: msg.writer_target || null,
  output_port: Number.isFinite(Number(msg._writer_port)) ? Number(msg._writer_port) : 1,
  raw_payload: payload,
  raw_topic: msg.topic || null,
  raw_error: null,
  normalized_at: now
};
let event = 'ACK';
let reason = null;
if (result.protocol === 'modbus') {
  if (result.output_port === 2) {
    event = 'FAULT';
    reason = 'modbus fail output';
  }
  if (payload && typeof payload === 'object') {
    const ex = payload.exceptionCode;
    const status = String(payload.status || payload.modbusStatus || payload.message || '').toLowerCase();
    if (payload.isException === true || ex !== undefined) {
      event = String(ex) === '6' ? 'BUSY' : 'FAULT';
      reason = ex !== undefined ? ('modbus exception ' + ex) : 'modbus exception';
    } else if (status.includes('busy')) {
      event = 'BUSY';
      reason = payload.status || payload.message || 'modbus busy';
    } else if (status.includes('fault') || status.includes('fail') || status.includes('error') || status.includes('bad')) {
      event = 'FAULT';
      reason = payload.status || payload.message || 'modbus write failed';
    }
  }
} else if (result.protocol === 'opcua') {
  const statusCode = String(msg.statusCode || (payload && (payload.statusCode || payload.status || payload.serviceResult)) || '').trim();
  const s = statusCode.toLowerCase();
  result.statusCode = statusCode || null;
  if (!statusCode) {
    event = result.output_port === 1 ? 'ACK' : 'FAULT';
    reason = result.output_port === 1 ? null : 'opcua non-success output';
  } else if (s.includes('good')) {
    event = 'ACK';
  } else if (s.includes('busy') || s.includes('waiting') || s.includes('pending') || s.includes('uncertain')) {
    event = 'BUSY';
    reason = statusCode;
  } else {
    event = 'FAULT';
    reason = statusCode;
  }
} else if (result.protocol === 'mcprotocol') {
  if (payload && typeof payload === 'object') {
    const status = String(payload.status || payload.result || payload.message || '').toLowerCase();
    if (status.includes('busy')) {
      event = 'BUSY';
      reason = payload.status || payload.message || 'mc busy';
    } else if (status.includes('fault') || status.includes('fail') || status.includes('error') || status.includes('bad')) {
      event = 'FAULT';
      reason = payload.status || payload.message || 'mc write failed';
    }
  }
}
